import { useState, useEffect } from 'react'
import { usePublicClient } from 'wagmi'
import { useGuestChain } from './useGuestChain.js'
import { parseUnits } from 'viem'
import { loadTickets, deleteTicket, deleteTicketsByChain, encodeTicket, updateTicketStatus } from './ticketUtils.js'
import { getChainInfo, getTxUrl } from './chainUtils.js'
import { getVaultAddress, getDeployBlock } from './config.js'
import { VAULT_ABI } from './abi.js'
import { useTicketStatus, setTicketStatusGlobal, setTicketStatusBatch, getTicketStatus } from './useTicketStatus.js'

const NULLIFIER_ABI = [{ type:'function', name:'nullifierUsed', inputs:[{type:'uint256'}], outputs:[{type:'bool'}], stateMutability:'view' }]
const DEPOSIT_EVENT = { type:'event', name:'Deposit', inputs:[{name:'leaf',type:'uint256',indexed:true},{name:'leafIndex',type:'uint256',indexed:false},{name:'actualAmount',type:'uint256',indexed:false}] }
const BATCH = 49000n
const PAGE_SIZE = 8


function statusInfo(s) {
  if (s === 'checking')  return { label: 'Checking…', dot: '#888' }
  if (s === 'withdrawn') return { label: 'Withdrawn',  dot: '#555' }
  if (s === 'available') return { label: 'Available',  dot: '#00d395' }
  return                        { label: 'Pending',    dot: '#f0a500' }
}

function timeAgo(ts) {
  if (!ts) return ''
  const mins = Math.floor((Date.now() - ts) / 60000)
  if (mins < 60) return `${mins}m`
  const hrs = Math.floor(mins / 60)
  if (hrs < 24) return `${hrs}h`
  return `${Math.floor(hrs / 24)}d ${hrs % 24}h`
}

function shortHash(h, pre=6, suf=4) {
  if (!h || h.length < pre+suf+3) return h
  return h.slice(0,pre) + '…' + h.slice(-suf)
}

export default function Tickets({ onWithdraw, onDeposit, active }) {
  const { activeChainId: chainId } = useGuestChain()
  const { currency } = getChainInfo(chainId)
  const publicClient = usePublicClient()
  const [tickets, setTickets] = useState([])
  const [copied, setCopied] = useState(null)
  const [confirmDelete, setConfirmDelete] = useState(null)
  const [confirmDeleteAll, setConfirmDeleteAll] = useState(false)
  const [expanded, setExpanded] = useState({})
  const status = useTicketStatus()
  const [anonSet, setAnonSet] = useState({})
  const [nullifierHashes, setNullifierHashes] = useState({})
  const [page, setPage] = useState(0)

  function refresh() { setTickets(loadTickets().filter(t => t.chainId === chainId).reverse()) }

  useEffect(() => { refresh(); setPage(0) }, [chainId]) // eslint-disable-line
  useEffect(() => { if (active) { refresh(); setPage(0) } }, [active]) // eslint-disable-line

  async function checkAnonSet(n, vaultAddress) {
    try {
      const RANK_ABI = [
        { type:'function', name:'commitmentAmountRank', inputs:[{type:'uint256'}], outputs:[{type:'uint256'}], stateMutability:'view' },
        { type:'function', name:'amountDepositCount', inputs:[{type:'address'},{type:'uint256'}], outputs:[{type:'uint256'}], stateMutability:'view' },
      ]
      const resolvedToken = n.token ?? '0x0000000000000000000000000000000000000000'
      const [rank, total] = await Promise.all([
        publicClient.readContract({ address: vaultAddress, abi: RANK_ABI, functionName: 'commitmentAmountRank', args: [BigInt(n.commitment)] }),
        publicClient.readContract({ address: vaultAddress, abi: RANK_ABI, functionName: 'amountDepositCount', args: [resolvedToken, parseUnits(n.amount, n.decimals ?? 18)] }),
      ])
      const after = Number(total) - Number(rank) - 1
      setAnonSet(p => ({ ...p, [n.commitment]: after }))
    } catch(e) { console.error('[checkAnonSet]', e?.message) }
  }

  async function checkTicket(n) {
    const vaultAddress = getVaultAddress(chainId)
    if (n.status === 'used') {
      setTicketStatusGlobal(n.commitment, 'withdrawn')
      await checkAnonSet(n, vaultAddress)
      return
    }
    try {
      const nhash = n.nullifierHash ?? (await window.__zk.poseidon([BigInt(n.nullifier)])).toString()
      setNullifierHashes(p => ({ ...p, [n.commitment]: nhash }))
      const deployBlock  = getDeployBlock(chainId)
      const spent = await publicClient.readContract({
        address: vaultAddress, abi: NULLIFIER_ABI,
        functionName: 'nullifierUsed', args: [BigInt(nhash)],
      })
      if (spent) {
        setTicketStatusGlobal(n.commitment, 'withdrawn')
        await checkAnonSet(n, vaultAddress)
        return
      }

      const alreadyOnChain = n.status === 'deposited' || getTicketStatus()[n.commitment] === 'available'
      let onChain = alreadyOnChain
      const resolvedToken = n.token ?? '0x0000000000000000000000000000000000000000'

      if (!alreadyOnChain) {
        const latest = await publicClient.getBlockNumber()
        for (let from = deployBlock; from <= latest && !onChain; from += BATCH) {
          const to = from + BATCH - 1n < latest ? from + BATCH - 1n : latest
          const logs = await publicClient.getLogs({ address: vaultAddress, event: DEPOSIT_EVENT, args: { leaf: BigInt(n.commitment) }, fromBlock: from, toBlock: to })
          if (logs.length > 0) { onChain = true }
        }
      }

      if (onChain) {
        updateTicketStatus(n.commitment, 'deposited')
        setTicketStatusGlobal(n.commitment, 'available')
        await checkAnonSet(n, vaultAddress)
      } else {
        setTicketStatusGlobal(n.commitment, 'pending')
      }
    } catch (e) { console.error('[checkTicket]', n.commitment?.slice(0,10), e?.message || e); setTicketStatusGlobal(n.commitment, 'pending') }
  }

  const [zkReady, setZkReady] = useState(false)
  useEffect(() => { window.__zkReady.then(() => setZkReady(true)) }, [])

  // On mount (tab switch) + whenever tickets/zkReady change: only check uncached tickets
  useEffect(() => {
    if (!publicClient || !tickets.length || !zkReady) return
    const cached = getTicketStatus()
    const needCheck = tickets.filter(n => {
      const s = cached[n.commitment]
      return !s || s === 'checking' || s === 'pending'
    })
    const init = {}
    needCheck.forEach(n => { if (!cached[n.commitment]) init[n.commitment] = 'checking' })
    if (Object.keys(init).length) setTicketStatusBatch(init)
    needCheck.forEach(n => checkTicket(n))
    // Fetch anonSet for all settled tickets every time
    const vaultAddress = getVaultAddress(chainId)
    tickets.filter(n => {
      const s = cached[n.commitment]
      return s === 'available' || s === 'deposited' || s === 'withdrawn' || s === 'used'
    }).forEach(n => checkAnonSet(n, vaultAddress))
  }, [tickets.length, publicClient, zkReady]) // eslint-disable-line

  // Poll pending/checking tickets every 5s
  useEffect(() => {
    if (!publicClient || !zkReady) return
    const pending = tickets.filter(n => { const s = status[n.commitment]; return s === 'pending' || s === 'checking' })
    if (!pending.length) return
    const iv = setInterval(() => pending.forEach(n => checkTicket(n)), 8000)
    return () => clearInterval(iv)
  }, [tickets, status, publicClient, zkReady]) // eslint-disable-line

  function copy(n) {
    navigator.clipboard.writeText(encodeTicket(n))
    setCopied(n.commitment)
    setTimeout(() => setCopied(null), 2000)
  }

  function remove(commitment) { deleteTicket(commitment); refresh(); setConfirmDelete(null) }
  function removeAll() { deleteTicketsByChain(chainId); refresh(); setConfirmDeleteAll(false) }

  if (!tickets.length) return (
    <div className="card">
      <div className="tkt-empty-wrap">
        <div className="tkt-empty-icon">🎫</div>
        <h2 className="tkt-empty-title">No Tickets Yet</h2>
        <p className="tkt-empty-sub">Tickets are stored locally in your browser.<br/>Deposit to generate your first ticket.</p>
        <button className="btn-primary" onClick={onDeposit}>Make a Deposit →</button>
      </div>
    </div>
  )

  const totalPages = Math.ceil(tickets.length / PAGE_SIZE)
  const pageTickets = tickets.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE)
  const availableCount = tickets.filter(t => status[t.commitment] === 'available').length
  const withdrawnCount = tickets.filter(t => status[t.commitment] === 'withdrawn').length

  return (
    <div className="card">
      <div className="tickets-header">
        <div style={{display:'flex',alignItems:'center',gap:8}}>
          <h2 style={{margin:0}}>My Tickets</h2>
          {confirmDeleteAll
            ? <>
                <span style={{fontSize:12,color:'rgba(255,255,255,0.6)'}}>Delete all?</span>
                <button className="tkt-btn tkt-btn-danger" onClick={removeAll}>Confirm</button>
                <button className="tkt-btn" onClick={() => setConfirmDeleteAll(false)}>Cancel</button>
              </>
            : <button className="tkt-btn tkt-btn-del" onClick={() => setConfirmDeleteAll(true)} title="Delete all tickets on this chain">Delete All</button>
          }
        </div>
        <div className="tickets-summary">
          <span className="tickets-summary-num" style={{color:'#00d395',fontSize:18,fontWeight:700}}>{availableCount}</span>
          <span className="tickets-summary-lbl" style={{color:'#00d395',fontWeight:600}}>available</span>
          <span className="tickets-summary-sep" />
          <span className="tickets-summary-num" style={{color:'rgba(255,255,255,0.3)'}}>{withdrawnCount}</span>
          <span className="tickets-summary-lbl">withdrawn</span>
        </div>
      </div>

      <div className="tickets-list">
        {pageTickets.map((n, i) => {
          const s = status[n.commitment] ?? 'checking'
          const si = statusInfo(s)
          const isWithdrawn = s === 'withdrawn'
          const canWithdraw = s === 'available'
          const isExpanded = expanded[n.commitment]
          const tokenLabel = n.token === '0x0000000000000000000000000000000000000000' ? currency : (n.token ? shortHash(n.token) : currency)
          const after = anonSet[n.commitment]
          const age = timeAgo(n.savedAt)

          return (
            <div key={n.commitment} className={`tkt-card${isWithdrawn ? ' tkt-dim' : ''}${canWithdraw ? ' tkt-available' : ''}`}>
              {/* Main row */}
              <div className="tkt-row">
                <span className="tkt-idx">#{String(n.seq).padStart(2,'0')}</span>
                <span className="tkt-amount">{n.amount} <span className="tkt-cur">{tokenLabel}</span></span>
                {age && <span className="tkt-age">{age}</span>}
                {n.txHash
                  ? <a className="tkt-tx" href={getTxUrl(n.chainId ?? chainId, n.txHash)} target="_blank" rel="noreferrer">{shortHash(n.txHash, 4, 4)}</a>
                  : <span className="tkt-tx">…</span>
                }
                <span className="tkt-dot" style={{background: si.dot}} title={si.label} />
                <span className={`tkt-status s-${s}`}>{si.label}</span>
                {after !== undefined && (
                  <span className="tkt-anon" title={`Anonymity set: ${Math.max(0,after)} deposit(s) after yours — more is better`} style={{color: after >= 10 ? '#00d395' : after >= 3 ? '#f0a500' : '#f43f5e'}}>
                    🛡 {after >= 10 ? 'High' : after >= 3 ? 'Med' : 'Low'} ({Math.max(0,after)})
                  </span>
                )}
                <div className="tkt-actions">
                  {canWithdraw && (
                    <button className="tkt-btn tkt-btn-primary" onClick={() => onWithdraw(encodeTicket(n))}>Withdraw</button>
                  )}
                  <button className="tkt-btn" onClick={() => copy(n)}>{copied === n.commitment ? '✓' : '📋'}</button>
                  <button className="tkt-btn tkt-btn-del" onClick={() => setConfirmDelete(n.commitment)}>✕</button>
                </div>
              </div>

              {/* Confirm delete */}
              {confirmDelete === n.commitment && (
                <div className="tkt-confirm">
                  <span>Delete this ticket?</span>
                  <button className="tkt-btn tkt-btn-danger" onClick={() => remove(n.commitment)}>Delete</button>
                  <button className="tkt-btn" onClick={() => setConfirmDelete(null)}>Cancel</button>
                </div>
              )}


            </div>
          )
        })}
      </div>

      {totalPages > 1 && (
        <div className="tkt-pagination">
          <button className="tkt-btn" disabled={page === 0} onClick={() => setPage(p => p - 1)}>‹</button>
          <span className="tkt-page-info">{page + 1} / {totalPages}</span>
          <button className="tkt-btn" disabled={page === totalPages - 1} onClick={() => setPage(p => p + 1)}>›</button>
        </div>
      )}
    </div>
  )
}
